import pathlib,json,subprocess,os,re
b=pathlib.Path('.build/cp410');rows=json.loads((b/'probes.json').read_text());names=['official-sort','captured-sort','sort-index','sort-identity','map-identity','sort-arithmetic','call-scalar','call-closure','call-callback','official-bfs','official-json-transform','frequency'];
life=[];binary=str((b/'lifecycle/nift-counter').resolve())
for name in names:
 candidates=[r for r in rows if r['name']==name];r=next((x for x in candidates if x['n']==2000),candidates[0]);q=subprocess.run([binary,r['path']],capture_output=True,text=True,check=True);assert q.stdout.strip()==r['expected'];m=re.search(r'value-counts ctor=(\d+) copy_ctor=(\d+) move_ctor=(\d+) copy_assign=(\d+) move_assign=(\d+) dtor=(\d+)',q.stderr);assert m;qdata=dict(name=name,n=r['n'],counts=dict(zip(['constructors','copy_constructors','move_constructors','copy_assignments','move_assignments','destructors'],map(int,m.groups()))));deep=re.search(r'deep-copy-counts aggregates=(\d+) child_values=(\d+)',q.stderr);assert deep;qdata['counts'].update(aggregate_copy_operations=int(deep[1]),immediate_children_copied=int(deep[2]));life.append(qdata);(b/'lifecycle/counts.json').write_text(json.dumps(life,indent=2)+'\n');print('LIFECYCLE',name,qdata['counts'],flush=True)
